column1:
CREATE TABLE cnt ( -- Страны.
  c01 SMALLINT NOT NULL, -- Идентификатор страны.
  c02 VARCHAR(50) NOT NULL, -- Название страны.
  c03 TIMESTAMP, -- Дата изменения записи.
  PRIMARY KEY (c01)
);

CREATE TABLE lng ( -- Языки.
  f01 SMALLINT NOT NULL, -- Идентификатор языка.
  f02 CHAR(20) NOT NULL, -- Название языка.
  f03 TIMESTAMP NOT NULL, -- Дата изменения записи.
  PRIMARY KEY (f01)
);

CREATE TABLE cat ( -- Категории фильмов.
  g01 SMALLINT NOT NULL, -- Идентификатор категории.
  g02 VARCHAR(25) NOT NULL, -- Название категории.
  g03 TIMESTAMP NOT NULL, -- Дата изменения записи.
  PRIMARY KEY (g01)
);

CREATE TABLE flt ( -- Текстовая таблица для полнотекстового поиска.
  m01 SMALLINT NOT NULL, -- Идентификатор фильма.
  m02 VARCHAR(255) NOT NULL, -- Название фильма.
  m03 BLOB SUB_TYPE TEXT, -- Описание фильма.
  PRIMARY KEY (m01)
);
